{"command": "cat > test_parser.py <<EOF
import ast
import operator

def evaluate_node(node, user):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id in user:
            return user[node.id]
        raise ValueError(f"Unknown variable: {node.id}")
    elif isinstance(node, ast.Compare):
        left = evaluate_node(node.left, user)
        if len(node.ops) != 1:
            raise ValueError("Only single comparison supported")
        op = node.ops[0]
        right = evaluate_node(node.comparators[0], user)

        if isinstance(op, ast.Eq): return left == right
        if isinstance(op, ast.NotEq): return left != right
        if isinstance(op, ast.Lt): return left < right
        if isinstance(op, ast.LtE): return left <= right
        if isinstance(op, ast.Gt): return left > right
        if isinstance(op, ast.GtE): return left >= right
        raise ValueError(f"Unsupported op: {type(op)}")
    elif isinstance(node, ast.BoolOp):
        values = [evaluate_node(v, user) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError(f"Unsupported bool op: {type(node.op)}")
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not evaluate_node(node.operand, user)
        raise ValueError(f"Unsupported unary op: {type(node.op)}")
    else:
        raise ValueError(f"Unsupported node: {type(node)}")

def validate_node(node):
    if isinstance(node, (ast.Constant, ast.Name)):
        return True
    if isinstance(node, ast.Compare):
        return all(validate_node(n) for n in [node.left] + node.comparators)
    if isinstance(node, ast.BoolOp):
        return all(validate_node(n) for n in node.values)
    if isinstance(node, ast.UnaryOp):
        return isinstance(node.op, ast.Not) and validate_node(node.operand)
    return False

# Test it
user = {"id": 1, "name": "Ada", "email": "ada@example.com"}
expr = "name == 'Ada' and id > 0"
tree = ast.parse(expr, mode='eval')
print(validate_node(tree.body))
print(evaluate_node(tree.body, user))

